"use client"

/** @responsibility Renders the pannable, zoomable canvas viewport and orchestrates viewport state, pointer and keyboard navigation, and connection gestures for its nodes and edges. */

import * as React from "react"

import { cn } from "@/lib/utils"

import {
  WorkflowCanvasContext,
  WorkflowCanvasNodeContext,
  WorkflowCanvasViewportContext,
  composeWorkflowCanvasRefs,
  createWorkflowCanvasConnectionStore,
  createWorkflowCanvasGeometryStore,
  useWorkflowCanvasViewport,
  type WorkflowCanvasConnection,
  type WorkflowCanvasConnectionEnd,
  type WorkflowCanvasContextValue,
} from "./workflow-canvas-context"
import {
  clampViewportToBounds,
  nodeAnchorPoint,
  screenPointToCanvasPoint,
  zoomViewportAtPoint,
  type WorkflowCanvasBounds,
  type WorkflowCanvasPoint,
  type WorkflowCanvasViewport,
} from "./workflow-canvas-math"

/**
 * What produced a viewport change: a gesture, or the canvas re-clamping
 * itself into its bounds after mounting or resizing.
 */
type WorkflowCanvasViewportTrigger =
  | "pointer"
  | "wheel"
  | "keyboard"
  | "resize"

/**
 * The background pointers currently steering the viewport, by pointer id.
 * One pointer pans incrementally; two pinch-zoom around their midpoint.
 */
type WorkflowCanvasBackgroundPointers = Map<
  number,
  { clientX: number; clientY: number }
>

/** Properties accepted by the WorkflowCanvas viewport. */
interface WorkflowCanvasProps
  extends Omit<React.ComponentProps<"div">, "onWheel"> {
  /**
   * Called before the canvas pans or zooms on a wheel event. The listener
   * must be non-passive to suppress page scrolling, so it is attached
   * directly to the element and this receives the NATIVE `WheelEvent`
   * rather than React's synthetic one. Call `preventDefault()` to claim
   * the event and leave the viewport untouched.
   */
  onWheel?: (event: WheelEvent) => void
  /**
   * The viewport when the canvas is controlled by its consumer.
   * Interactions report the next viewport through `onViewportChange`; the
   * consumer renders it back through this property.
   */
  viewport?: WorkflowCanvasViewport
  /**
   * Initial viewport for an uncontrolled canvas.
   * @defaultValue `{ x: 0, y: 0, zoom: 1 }`
   */
  defaultViewport?: WorkflowCanvasViewport
  /** Called with the next viewport on every step of an interaction. */
  onViewportChange?: (
    viewport: WorkflowCanvasViewport,
    meta: { trigger: WorkflowCanvasViewportTrigger },
  ) => void
  /**
   * The canvas region panning and node dragging are confined to, in canvas
   * units. Omit for an infinite canvas.
   */
  bounds?: WorkflowCanvasBounds
  /**
   * Smallest allowed zoom.
   * @defaultValue 0.25
   */
  minZoom?: number
  /**
   * Largest allowed zoom.
   * @defaultValue 2
   */
  maxZoom?: number
  /**
   * Screen pixels one arrow-key press pans the focused canvas.
   * @defaultValue 48
   */
  keyboardPanStep?: number
  /**
   * Canvas units one arrow-key press moves a focused node.
   * @defaultValue 8
   */
  keyboardMoveStep?: number
  /** Called when a connection gesture settles between two nodes. */
  onConnect?: (connection: WorkflowCanvasConnection) => void
  /**
   * Called when a drawn connection is released over empty canvas, with the
   * drop point in canvas units — the moment to present follow-up UI there,
   * such as a palette of nodes to create and attach.
   */
  onConnectEnd?: (end: WorkflowCanvasConnectionEnd) => void
  /**
   * Called when the user walks away — pressing the open background, or
   * pressing one of `dismissKeys` anywhere in the canvas. Use it to close
   * transient UI such as a palette opened from `onConnectEnd`.
   */
  onDismiss?: () => void
  /**
   * Keys that trigger `onDismiss`.
   * @defaultValue `["Escape"]`
   */
  dismissKeys?: readonly string[]
  /**
   * Whether the canvas is a read-only view: nodes cannot be dragged, moved
   * with the keyboard, or deleted, connection handles hide and stop
   * drawing, and pointer drags anywhere — nodes included — pan instead.
   * Panning, zooming, resizing, and collapse toggles stay available.
   *
   * Defaults to true for a canvas nested inside another canvas' node (a
   * subflow preview) and false at top level; pass an explicit value to
   * override either way.
   */
  readOnly?: boolean
}

/**
 * An infinite (or bounded) workflow canvas: a pannable, zoomable window onto
 * a plane of nodes and edges.
 *
 * Compose `WorkflowCanvasGrid` for the dotted backdrop, then a
 * `WorkflowCanvasSurface` holding `WorkflowCanvasEdges` and
 * `WorkflowCanvasNode` children. Drag the background or press arrow keys to
 * pan; pinch with two fingers, use a modifier-scroll, or press `+`/`-` to
 * zoom around the pinch midpoint, the pointer, or the center. The canvas is fully controlled when `viewport` is
 * provided; nothing is persisted internally.
 *
 * @param props - Controlled or uncontrolled viewport, zoom range, optional
 * bounds, connection callback, and native container properties.
 * @returns The canvas viewport element providing canvas context.
 */
function WorkflowCanvas({
  viewport: viewportProp,
  defaultViewport,
  onViewportChange,
  bounds,
  minZoom = 0.25,
  maxZoom = 2,
  keyboardPanStep = 48,
  keyboardMoveStep = 8,
  onConnect,
  onConnectEnd,
  onDismiss,
  dismissKeys = ["Escape"],
  readOnly,
  className,
  children,
  ref,
  onPointerDown,
  onPointerMove,
  onPointerUp,
  onPointerCancel,
  onKeyDown,
  onWheel,
  ...props
}: WorkflowCanvasProps) {
  const rootRef = React.useRef<HTMLDivElement>(null)
  const composedRef = React.useMemo(
    () => composeWorkflowCanvasRefs(rootRef, ref),
    [ref],
  )
  const [geometry] = React.useState(createWorkflowCanvasGeometryStore)
  const [connection] = React.useState(createWorkflowCanvasConnectionStore)
  // A canvas living inside another canvas' node is a subflow preview and
  // presents read-only unless the consumer says otherwise.
  const parentNode = React.useContext(WorkflowCanvasNodeContext)
  const resolvedReadOnly = readOnly ?? parentNode !== null
  const [internalViewport, setInternalViewport] = React.useState<
    WorkflowCanvasViewport
  >(defaultViewport ?? { x: 0, y: 0, zoom: 1 })
  const backgroundPointersRef = React.useRef<WorkflowCanvasBackgroundPointers>(
    new Map(),
  )

  const resolvedViewport = viewportProp ?? internalViewport
  const viewportRef = React.useRef(resolvedViewport)
  viewportRef.current = resolvedViewport
  // What this canvas actually renders, kept apart from the accumulator
  // above so a gesture can re-anchor on it when it resumes.
  // The pointer running a node drag, if any. A node drag lives inside the
  // node, but the canvas must know one is in flight so a second finger on
  // the background cannot pan or dismiss underneath it.
  const nodeDragPointerRef = React.useRef<number | null>(null)
  const renderedViewportRef = React.useRef(resolvedViewport)
  renderedViewportRef.current = resolvedViewport
  const lastWheelTimeRef = React.useRef(0)

  const resolvedBounds = bounds ?? null
  const boundsRef = React.useRef(resolvedBounds)
  boundsRef.current = resolvedBounds
  // A primitive stand-in for the bounds object, so the context value below
  // does not churn when a consumer writes `bounds` inline — which would
  // re-render every node, handle and edge on the canvas.
  const boundsKey = resolvedBounds
    ? `${resolvedBounds.minX},${resolvedBounds.minY},${resolvedBounds.maxX},${resolvedBounds.maxY}`
    : ""

  const callbacksRef = React.useRef({
    onViewportChange,
    onConnect,
    onConnectEnd,
    onDismiss,
    onWheel,
  })
  callbacksRef.current = {
    onViewportChange,
    onConnect,
    onConnectEnd,
    onDismiss,
    onWheel,
  }

  const zoomRangeRef = React.useRef({ minZoom, maxZoom })
  zoomRangeRef.current = { minZoom, maxZoom }

  const isControlledRef = React.useRef(viewportProp !== undefined)
  isControlledRef.current = viewportProp !== undefined

  const isConnecting = React.useSyncExternalStore(
    connection.subscribe,
    () => connection.get() !== null,
    () => false,
  )

  const applyViewport = React.useCallback(
    (next: WorkflowCanvasViewport, trigger: WorkflowCanvasViewportTrigger) => {
      const root = rootRef.current
      const size = root
        ? { width: root.clientWidth, height: root.clientHeight }
        : { width: 0, height: 0 }
      // An unmeasured canvas cannot resolve bound clamping yet; the raw
      // viewport keeps interactions working meanwhile.
      const clamped =
        size.width > 0 && size.height > 0
          ? clampViewportToBounds(next, boundsRef.current, size)
          : next
      const current = viewportRef.current

      if (
        clamped.x === current.x &&
        clamped.y === current.y &&
        clamped.zoom === current.zoom
      ) {
        return
      }

      // The ref always tracks the last viewport this canvas reported, so
      // rapid gesture steps compound instead of re-reading a stale base; a
      // controlled consumer's echo re-anchors it on the next render. The
      // internal state moves solely when the canvas owns its viewport.
      viewportRef.current = clamped

      if (!isControlledRef.current) {
        setInternalViewport(clamped)
      }

      callbacksRef.current.onViewportChange?.(clamped, { trigger })
    },
    [],
  )

  // An ancestor transform (an outer canvas' surface, for example) scales
  // this canvas on screen; every client-pixel measurement divides by this
  // so nested canvases track the pointer exactly.
  const getScreenScale = React.useCallback((): number => {
    const root = rootRef.current

    if (!root || root.offsetWidth === 0) {
      return 1
    }

    const scale = root.getBoundingClientRect().width / root.offsetWidth

    return Number.isFinite(scale) && scale > 0 ? scale : 1
  }, [])

  const clientPointToCanvasPoint = React.useCallback(
    (clientX: number, clientY: number): WorkflowCanvasPoint => {
      const root = rootRef.current
      const rect = root?.getBoundingClientRect()
      const scale = getScreenScale()

      // The surface sits in the root's content box, so a canvas styled
      // with a border starts one border-width inside its rectangle.
      return screenPointToCanvasPoint(
        {
          x: (clientX - (rect?.left ?? 0)) / scale - (root?.clientLeft ?? 0),
          y: (clientY - (rect?.top ?? 0)) / scale - (root?.clientTop ?? 0),
        },
        // The rendered viewport, not the gesture accumulator: pointer
        // coordinates must map against the frame the pointer is over.
        renderedViewportRef.current,
      )
    },
    [getScreenScale],
  )

  const cancelConnection = React.useCallback(() => {
    connection.set(null)
  }, [connection])

  const contextValue = React.useMemo<WorkflowCanvasContextValue>(
    () => ({
      geometry,
      connection,
      // What is on screen — not the accumulator the canvas' own gestures
      // advance — so a controlled consumer that declines a change never
      // has node drags converted at a viewport it rejected.
      getViewport: () => renderedViewportRef.current,
      getRootElement: () => rootRef.current,
      getScreenScale,
      getBounds: () => boundsRef.current,
      boundsKey,
      readOnly: resolvedReadOnly,
      keyboardMoveStep,
      clientPointToCanvasPoint,
      beginConnection: (source, sourceSide, mode) => {
        const sourceGeometry = geometry.get(source)
        const point = sourceGeometry
          ? nodeAnchorPoint(sourceGeometry, sourceSide)
          : { x: 0, y: 0 }

        connection.set({ source, sourceSide, point, mode })
      },
      moveConnection: (clientX, clientY) => {
        const pending = connection.get()

        if (pending) {
          connection.set({
            ...pending,
            point: clientPointToCanvasPoint(clientX, clientY),
          })
        }
      },
      completeConnection: (target, targetSide) => {
        const pending = connection.get()

        connection.set(null)

        // A connection dropped back onto its own node is a cancel, not a
        // self-loop — and a target this canvas has never registered (for
        // example an id from a foreign canvas) can never be reported.
        if (
          pending &&
          pending.source !== target &&
          geometry.get(target) !== undefined
        ) {
          callbacksRef.current.onConnect?.({
            source: pending.source,
            sourceSide: pending.sourceSide,
            target,
            targetSide,
          })
        }
      },
      endConnectionAtPoint: (point) => {
        const pending = connection.get()

        connection.set(null)

        if (pending) {
          callbacksRef.current.onConnectEnd?.({
            source: pending.source,
            sourceSide: pending.sourceSide,
            point,
          })
        }
      },
      cancelConnection,
      claimNodeDrag: (pointerId) => {
        nodeDragPointerRef.current = pointerId
      },
      releaseNodeDrag: (pointerId) => {
        if (nodeDragPointerRef.current === pointerId) {
          nodeDragPointerRef.current = null
        }
      },
      hasNodeDrag: () => nodeDragPointerRef.current !== null,
      revealRegion: (region) => {
        const root = rootRef.current

        if (!root) {
          return
        }

        const current = renderedViewportRef.current
        const margin = 24
        const left = region.x * current.zoom + current.x
        const top = region.y * current.zoom + current.y
        const right = left + region.width * current.zoom
        const bottom = top + region.height * current.zoom
        let { x, y } = current

        // Only the axes that fall outside move, and each moves the least
        // distance that brings the region back inside the window.
        const viewLeft = margin
        const viewRight = root.clientWidth - margin
        const viewTop = margin
        const viewBottom = root.clientHeight - margin

        // A region too large to fit can never sit fully inside, so it
        // counts as revealed while it still covers the window, and only
        // re-anchors to its start edge once it has drifted clear of one —
        // aligning its far edge instead would push a tall node's header,
        // and the controls on it, off screen. Without that hysteresis the
        // oversized case would re-anchor on every keystroke, pinning the
        // node in place while the arrow keys appear to do nothing.
        if (right - left > viewRight - viewLeft) {
          if (left > viewLeft) x += viewLeft - left
          else if (right < viewRight) x -= right - viewRight
        } else if (left < viewLeft) x += viewLeft - left
        else if (right > viewRight) x -= right - viewRight

        if (bottom - top > viewBottom - viewTop) {
          if (top > viewTop) y += viewTop - top
          else if (bottom < viewBottom) y -= bottom - viewBottom
        } else if (top < viewTop) y += viewTop - top
        else if (bottom > viewBottom) y -= bottom - viewBottom

        if (x !== current.x || y !== current.y) {
          applyViewport({ x, y, zoom: current.zoom }, "keyboard")
        }
      },
    }),
    [
      applyViewport,
      cancelConnection,
      clientPointToCanvasPoint,
      connection,
      boundsKey,
      geometry,
      getScreenScale,
      keyboardMoveStep,
      resolvedReadOnly,
    ],
  )

  React.useEffect(() => {
    // A canvas turning read-only walks away from any in-flight connection.
    if (resolvedReadOnly) {
      connection.set(null)
    }
  }, [connection, resolvedReadOnly])

  // A pointer-drawn connection promises Escape as its way out, but the
  // press that started it focused nothing in Safari or Firefox — so while
  // one is in flight, Escape is heard at the document level.
  React.useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault()
        cancelConnection()
      }
    }

    let listening = false

    const sync = () => {
      const shouldListen = connection.get()?.mode === "pointer"

      if (shouldListen && !listening) {
        document.addEventListener("keydown", handleKeyDown, true)
        listening = true
      } else if (!shouldListen && listening) {
        document.removeEventListener("keydown", handleKeyDown, true)
        listening = false
      }
    }

    const unsubscribe = connection.subscribe(sync)

    sync()

    return () => {
      unsubscribe()

      if (listening) {
        document.removeEventListener("keydown", handleKeyDown, true)
      }
    }
  }, [cancelConnection, connection])

  // A controlled viewport arrives outside any gesture, so bounds would
  // otherwise never touch it: the canvas would render out-of-bounds space
  // until the first gesture snapped it back. Re-clamping on every change
  // corrects the consumer's state through onViewportChange instead. Only
  // an actually out-of-bounds render applies anything — re-applying an
  // in-bounds one would stomp gesture steps still accumulating between
  // renders.
  React.useEffect(() => {
    const root = rootRef.current

    if (!root) {
      return
    }

    const size = { width: root.clientWidth, height: root.clientHeight }

    if (size.width <= 0 || size.height <= 0) {
      return
    }

    const rendered = renderedViewportRef.current
    const { minZoom: min, maxZoom: max } = zoomRangeRef.current

    // Zoom is policed on arrival too, anchored at the middle so the
    // correction reads as a zoom about the centre rather than a jump.
    // Left to the gesture handlers alone, an out-of-range controlled zoom
    // would render as given and snap on the first wheel tick.
    const inRange =
      rendered.zoom < min || rendered.zoom > max
        ? zoomViewportAtPoint(
            rendered,
            { x: size.width / 2, y: size.height / 2 },
            rendered.zoom,
            min,
            max,
          )
        : rendered
    const clamped = clampViewportToBounds(inRange, boundsRef.current, size)

    if (
      clamped.x !== rendered.x ||
      clamped.y !== rendered.y ||
      clamped.zoom !== rendered.zoom
    ) {
      applyViewport(clamped, "resize")
    }
  }, [
    applyViewport,
    boundsKey,
    resolvedViewport.x,
    resolvedViewport.y,
    resolvedViewport.zoom,
  ])

  React.useEffect(() => {
    const root = rootRef.current

    if (!root || typeof ResizeObserver === "undefined") {
      return
    }

    // Bounds otherwise apply only to what an interaction produces, so an
    // initial viewport could start outside them and a resized canvas could
    // reveal space beyond them until the next gesture. Re-clamping on
    // mount and on every resize keeps the window inside its region.
    const clampToBounds = () => {
      applyViewport(viewportRef.current, "resize")
    }

    clampToBounds()

    const observer = new ResizeObserver(clampToBounds)

    observer.observe(root)

    return () => observer.disconnect()
  }, [applyViewport, boundsKey])

  React.useEffect(() => {
    const root = rootRef.current

    if (!root) {
      return
    }

    // Reads whether an element between the wheel target and the canvas
    // root can consume the scroll itself — an overflowing list inside a
    // node, an editable field — so the canvas leaves those wheels alone.
    const contentConsumesWheel = (
      target: EventTarget | null,
      event: WheelEvent,
    ): boolean => {
      let element = target instanceof Element ? target : null

      while (element && element !== root) {
        if (
          element.matches(
            'input, textarea, select, [contenteditable="true"], [data-workflow-canvas-no-drag]',
          )
        ) {
          return true
        }

        if (element instanceof HTMLElement) {
          const style = getComputedStyle(element)
          const scrollsY =
            /(auto|scroll)/.test(style.overflowY) &&
            element.scrollHeight > element.clientHeight
          const scrollsX =
            /(auto|scroll)/.test(style.overflowX) &&
            element.scrollWidth > element.clientWidth

          if (
            (event.deltaY !== 0 && scrollsY) ||
            (event.deltaX !== 0 && scrollsX)
          ) {
            return true
          }
        }

        element = element.parentElement
      }

      return false
    }

    // React registers wheel listeners passively, which cannot suppress the
    // page scrolling underneath the canvas, so the listener is attached
    // directly to the canvas element instead. The consumer's onWheel still
    // runs first and may preventDefault to claim the event.
    const handleWheel = (event: WheelEvent) => {
      if (contentConsumesWheel(event.target, event)) {
        return
      }

      // Wheel deltas only arrive in pixels from DOM_DELTA_PIXEL devices;
      // Firefox reports lines and page-scroll wheels report pages, so both
      // are converted before any of the transform math sees them.
      const deltaScale =
        event.deltaMode === 1 ? 16 : event.deltaMode === 2 ? root.clientHeight : 1
      const deltaX = event.deltaX * deltaScale
      const deltaY = event.deltaY * deltaScale

      // A wheel burst compounds from the viewport this canvas last
      // reported, but a burst arriving after a pause re-anchors on the
      // rendered viewport — so a controlled consumer that declines a
      // change is never accumulated against a viewport it rejected.
      const now = performance.now()

      if (now - lastWheelTimeRef.current > 150) {
        viewportRef.current = renderedViewportRef.current
      }

      lastWheelTimeRef.current = now

      callbacksRef.current.onWheel?.(event)

      if (event.defaultPrevented) {
        return
      }

      event.preventDefault()
      event.stopPropagation()

      const current = viewportRef.current
      const scale = getScreenScale()

      if (event.ctrlKey || event.metaKey) {
        const rect = root.getBoundingClientRect()
        const { minZoom: min, maxZoom: max } = zoomRangeRef.current

        applyViewport(
          zoomViewportAtPoint(
            current,
            {
              x: (event.clientX - rect.left) / scale - root.clientLeft,
              y: (event.clientY - rect.top) / scale - root.clientTop,
            },
            // A gentle exponent keeps one wheel notch to roughly a fifth
            // of a zoom step instead of crossing the whole range at once.
            current.zoom * Math.exp(-deltaY * 0.002),
            min,
            max,
          ),
          "wheel",
        )
      } else {
        applyViewport(
          {
            x: current.x - deltaX / scale,
            y: current.y - deltaY / scale,
            zoom: current.zoom,
          },
          "wheel",
        )
      }
    }

    root.addEventListener("wheel", handleWheel, { passive: false })

    return () => root.removeEventListener("wheel", handleWheel)
  }, [applyViewport, getScreenScale])

  const handlePointerDown = (event: React.PointerEvent<HTMLDivElement>) => {
    onPointerDown?.(event)
    // The canvas isolates its pointer gestures so a canvas nested inside a
    // node never pans or drags its host.
    event.stopPropagation()

    if (event.defaultPrevented || event.button !== 0) {
      return
    }

    const target = event.target as Element

    // Nodes, handles, interactive edges, and interactive elements own their
    // gestures; only the open background pans. On a read-only canvas nodes
    // and edges give up their gestures, so panning works from anywhere that
    // is not a control.
    if (
      target.closest(
        resolvedReadOnly
          ? 'button, a, input, textarea, select, [contenteditable="true"], [data-workflow-canvas-no-drag]'
          : '[data-slot="workflow-canvas-node"], [data-slot="workflow-canvas-handle"], [data-slot="workflow-canvas-edge"], button, a, input, textarea, select, [contenteditable="true"], [data-workflow-canvas-no-drag]',
      )
    ) {
      return
    }

    const pending = connection.get()

    // A connection or node drag a pointer is actively running belongs to
    // that pointer alone: a second finger landing on the background must
    // not destroy it, dismiss anything, or start panning underneath it —
    // a pan would slide the plane out from under the held node, which
    // tracks only its own finger's travel.
    if (pending?.mode === "pointer" || nodeDragPointerRef.current !== null) {
      return
    }

    // Pressing the open background walks away from whatever is in flight: a
    // connection someone armed but never finished, and any transient UI
    // the consumer has open.
    if (pending !== null) {
      cancelConnection()
    }

    callbacksRef.current.onDismiss?.()

    try {
      event.currentTarget.setPointerCapture(event.pointerId)
    } catch {
      // Synthetic pointer events (tests) have no capturable pointer id;
      // panning still works through the element's own move events.
    }

    // A new gesture starts from what the canvas actually renders, so a
    // controlled consumer that declined the last change is never panned
    // against a viewport it rejected.
    if (backgroundPointersRef.current.size === 0) {
      viewportRef.current = renderedViewportRef.current
    }

    backgroundPointersRef.current.set(event.pointerId, {
      clientX: event.clientX,
      clientY: event.clientY,
    })
  }

  const handlePointerMove = (event: React.PointerEvent<HTMLDivElement>) => {
    onPointerMove?.(event)

    const pointers = backgroundPointersRef.current
    const previous = pointers.get(event.pointerId)

    if (!previous) {
      return
    }

    const scale = getScreenScale()
    const current = viewportRef.current

    if (pointers.size === 1) {
      // One background pointer pans, incrementally: each step folds in any
      // viewport change that landed between moves (a wheel zoom, a
      // controlled update) instead of overwriting it.
      applyViewport(
        {
          x: current.x + (event.clientX - previous.clientX) / scale,
          y: current.y + (event.clientY - previous.clientY) / scale,
          zoom: current.zoom,
        },
        "pointer",
      )
    } else if (pointers.size === 2) {
      // Two background pointers pinch: zoom follows their spread, anchored
      // at the midpoint's previous position, while the midpoint's travel
      // pans — so the canvas point held between the fingers stays held.
      const other = [...pointers.entries()].find(
        ([pointerId]) => pointerId !== event.pointerId,
      )?.[1]

      if (other) {
        const rect = event.currentTarget.getBoundingClientRect()
        const previousDistance = Math.hypot(
          previous.clientX - other.clientX,
          previous.clientY - other.clientY,
        )
        const nextDistance = Math.hypot(
          event.clientX - other.clientX,
          event.clientY - other.clientY,
        )
        const previousMid = {
          x: (previous.clientX + other.clientX) / 2,
          y: (previous.clientY + other.clientY) / 2,
        }
        const nextMid = {
          x: (event.clientX + other.clientX) / 2,
          y: (event.clientY + other.clientY) / 2,
        }
        const { minZoom: min, maxZoom: max } = zoomRangeRef.current
        // The zoom anchors where the midpoint WAS: the separate travel
        // term below then carries that point to where the fingers are now.
        // Anchoring at the new midpoint instead would fold the travel into
        // the scaled term and count it twice.
        const zoomed = zoomViewportAtPoint(
          current,
          {
            x:
              (previousMid.x - rect.left) / scale -
              event.currentTarget.clientLeft,
            y:
              (previousMid.y - rect.top) / scale -
              event.currentTarget.clientTop,
          },
          current.zoom * (nextDistance / Math.max(previousDistance, 1e-6)),
          min,
          max,
        )

        applyViewport(
          {
            x: zoomed.x + (nextMid.x - previousMid.x) / scale,
            y: zoomed.y + (nextMid.y - previousMid.y) / scale,
            zoom: zoomed.zoom,
          },
          "pointer",
        )
      }
    }

    pointers.set(event.pointerId, {
      clientX: event.clientX,
      clientY: event.clientY,
    })
  }

  const handlePointerEnd = (event: React.PointerEvent<HTMLDivElement>) => {
    if (backgroundPointersRef.current.delete(event.pointerId)) {
      if (event.currentTarget.hasPointerCapture(event.pointerId)) {
        event.currentTarget.releasePointerCapture(event.pointerId)
      }
    }
  }

  const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event)

    if (event.defaultPrevented) {
      return
    }

    // Escape always abandons a pending connection first; a second press (or
    // any configured dismiss key) then reaches the consumer's transient UI.
    if (event.key === "Escape" && connection.get() !== null) {
      event.preventDefault()
      event.stopPropagation()
      cancelConnection()
      return
    }

    if (dismissKeys.includes(event.key) && callbacksRef.current.onDismiss) {
      event.preventDefault()
      event.stopPropagation()

      // The dismissal may unmount the very element holding focus (a
      // palette option, for example). If it does, the canvas takes focus —
      // matching the delete paths — but an Escape that closes something
      // elsewhere leaves the focused field alone.
      const root = rootRef.current
      const activeBefore =
        root && root.contains(document.activeElement)
          ? document.activeElement
          : null

      callbacksRef.current.onDismiss()

      if (activeBefore) {
        queueMicrotask(() => {
          if (!activeBefore.isConnected) {
            rootRef.current?.focus()
          }
        })
      }

      return
    }

    // Navigation keys act on the canvas itself, never on a focused node or
    // control inside it.
    if (event.target !== event.currentTarget) {
      return
    }

    // Keyboard steps start from what is rendered, the way pointer and
    // wheel gestures re-anchor, so a controlled consumer that declines a
    // change never leaves later key presses computing against a phantom.
    viewportRef.current = renderedViewportRef.current

    const current = viewportRef.current
    const step = keyboardPanStep
    let next: WorkflowCanvasViewport | undefined

    switch (event.key) {
      case "ArrowLeft":
        next = { ...current, x: current.x + step }
        break
      case "ArrowRight":
        next = { ...current, x: current.x - step }
        break
      case "ArrowUp":
        next = { ...current, y: current.y + step }
        break
      case "ArrowDown":
        next = { ...current, y: current.y - step }
        break
      case "+":
      case "=":
      case "-": {
        const root = rootRef.current
        const center = root
          ? { x: root.clientWidth / 2, y: root.clientHeight / 2 }
          : { x: 0, y: 0 }
        const factor = event.key === "-" ? 1 / 1.2 : 1.2

        next = zoomViewportAtPoint(
          current,
          center,
          current.zoom * factor,
          minZoom,
          maxZoom,
        )
        break
      }
    }

    if (next) {
      event.preventDefault()
      event.stopPropagation()
      applyViewport(next, "keyboard")
    }
  }

  return (
    <WorkflowCanvasContext.Provider value={contextValue}>
      <WorkflowCanvasViewportContext.Provider value={resolvedViewport}>
        {/* Consumer props spread first so the attributes the canvas owns
            (slot, role, gesture handlers) always win. */}
        <div
          role="application"
          tabIndex={0}
          {...props}
          ref={composedRef}
          data-slot="workflow-canvas"
          data-connecting={isConnecting ? "true" : undefined}
          data-readonly={resolvedReadOnly ? "true" : undefined}
          className={cn(
            // overflow-clip (not hidden) so the browser can never scroll
            // the clipped root to reveal a focused off-screen node, which
            // would silently desync every coordinate conversion.
            "group/workflow-canvas relative isolate box-border block h-full w-full touch-none select-none overflow-clip bg-background",
            "focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ring",
            className,
          )}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={(event) => {
            onPointerUp?.(event)
            handlePointerEnd(event)
          }}
          onPointerCancel={(event) => {
            onPointerCancel?.(event)
            handlePointerEnd(event)
          }}
          onKeyDown={handleKeyDown}
          onBlur={(event) => {
            props.onBlur?.(event)

            // Focus leaving the canvas entirely retires a keyboard-armed
            // connection, which otherwise waits indefinitely and would be
            // completed by an unrelated handle press much later.
            if (
              connection.get()?.mode === "keyboard" &&
              !event.currentTarget.contains(event.relatedTarget as Node | null)
            ) {
              cancelConnection()
            }
          }}
        >
          {children}
        </div>
      </WorkflowCanvasViewportContext.Provider>
    </WorkflowCanvasContext.Provider>
  )
}

/** Properties accepted by the canvas dot-grid backdrop. */
interface WorkflowCanvasGridProps extends React.ComponentProps<"div"> {
  /**
   * Canvas units between grid dots.
   * @defaultValue 24
   */
  gridSize?: number
}

/**
 * The dotted backdrop of a workflow canvas. The dots track the viewport, so
 * panning and zooming read as movement over an endless surface.
 *
 * @param props - The grid spacing and native container properties.
 * @returns A non-interactive full-bleed backdrop layer.
 */
function WorkflowCanvasGrid({
  gridSize = 24,
  className,
  style,
  ...props
}: WorkflowCanvasGridProps) {
  const viewport = useWorkflowCanvasViewport("WorkflowCanvasGrid")
  const spacing = gridSize * viewport.zoom

  return (
    <div
      aria-hidden="true"
      {...props}
      data-slot="workflow-canvas-grid"
      className={cn("pointer-events-none absolute inset-0", className)}
      style={{
        backgroundImage:
          "radial-gradient(circle, var(--border) 1px, transparent 1.5px)",
        backgroundSize: `${spacing}px ${spacing}px`,
        backgroundPosition: `${viewport.x}px ${viewport.y}px`,
        ...style,
      }}
    />
  )
}

/** Properties accepted by the transformed canvas surface. */
interface WorkflowCanvasSurfaceProps extends React.ComponentProps<"div"> {}

/**
 * The plane nodes and edges live on. The surface carries the viewport
 * transform as a single style, so panning and zooming never re-render the
 * nodes inside it.
 *
 * @param props - Native container properties; children are the canvas'
 * edges and nodes.
 * @returns The transformed content layer.
 */
function WorkflowCanvasSurface({
  className,
  style,
  ...props
}: WorkflowCanvasSurfaceProps) {
  const viewport = useWorkflowCanvasViewport("WorkflowCanvasSurface")

  return (
    <div
      {...props}
      data-slot="workflow-canvas-surface"
      className={cn(
        "absolute top-0 left-0 origin-top-left will-change-transform",
        className,
      )}
      style={
        {
          ...style,
          // The viewport transform composes with — never yields to — a
          // transform the consumer styles on.
          transform: `translate(${viewport.x}px, ${viewport.y}px) scale(${viewport.zoom})${
            typeof style?.transform === "string" ? ` ${style.transform}` : ""
          }`,
          // Published for descendants that must keep a constant SCREEN
          // size under this scale — the edge grab band, for one. SVG's
          // vector-effect cannot do it: the zoom is a CSS transform on an
          // HTML ancestor, outside the SVG's own coordinate chain.
          "--nessa-workflow-canvas-zoom": String(viewport.zoom),
        } as React.CSSProperties
      }
    />
  )
}

export {
  WorkflowCanvas,
  WorkflowCanvasGrid,
  WorkflowCanvasSurface,
  type WorkflowCanvasGridProps,
  type WorkflowCanvasProps,
  type WorkflowCanvasSurfaceProps,
  type WorkflowCanvasViewportTrigger,
}

"use client"

/** @responsibility Renders one draggable node on the canvas plane and the connection handles on its sides, owning drag, keyboard movement, and connection gestures. */

import * as React from "react"

import { cn } from "@/lib/utils"

import {
  WorkflowCanvasNodeContext,
  composeWorkflowCanvasRefs,
  useWorkflowCanvas,
  useWorkflowCanvasNodeGeometry,
  type WorkflowCanvasNodeContextValue,
} from "./workflow-canvas-context"
import {
  clampPositionToBounds,
  nearestNodeSide,
  type WorkflowCanvasPoint,
  type WorkflowCanvasSide,
} from "./workflow-canvas-math"

/**
 * The interaction that produced a node position change: a drag, an arrow
 * key, or the node growing until the canvas bounds pushed it back inside.
 */
type WorkflowCanvasNodeTrigger = "pointer" | "keyboard" | "resize"

/** State snapshotted for the lifetime of one node drag gesture. */
interface WorkflowCanvasNodeDragState {
  /** The pointer that started the gesture; other pointers are ignored. */
  pointerId: number
  startClientX: number
  startClientY: number
  /** Where the pointer was at the previous step, for incremental deltas. */
  lastClientX: number
  lastClientY: number
  /**
   * The position the pointer alone implies, before bounds are applied.
   * Tracking it separately keeps the grab offset: travelling past a bound
   * and back returns the node to the cursor rather than to the edge.
   */
  freePosition: WorkflowCanvasPoint
  latestPosition: WorkflowCanvasPoint
  /** Whether the pointer travelled far enough to count as a drag. */
  moved: boolean
}

/** Properties accepted by one canvas node. */
interface WorkflowCanvasNodeProps extends React.ComponentProps<"div"> {
  /** The node's unique id within its canvas, referenced by edges. */
  nodeId: string
  /**
   * The node's position in canvas units when it is controlled by its
   * consumer. Interactions report the next position through
   * `onPositionChange`; the consumer renders it back through this property.
   */
  position?: WorkflowCanvasPoint
  /** Initial position for an uncontrolled node. */
  defaultPosition?: WorkflowCanvasPoint
  /** Called with the next position on every step of an interaction. */
  onPositionChange?: (
    position: WorkflowCanvasPoint,
    meta: { trigger: WorkflowCanvasNodeTrigger },
  ) => void
  /** Called once per settled gesture with the final position. */
  onPositionCommit?: (position: WorkflowCanvasPoint) => void
  /** Whether the node presents as selected. */
  selected?: boolean
  /**
   * Whether the node presents collapsed when it is controlled by its
   * consumer: its `WorkflowCanvasNodeBody` children hide and only the rest
   * of its content — typically a header row — remains.
   */
  collapsed?: boolean
  /** Initial collapsed state for an uncontrolled node. */
  defaultCollapsed?: boolean
  /** Called when a toggle moves the node between collapsed and expanded. */
  onCollapsedChange?: (collapsed: boolean) => void
  /**
   * Called when Delete or Backspace is pressed on the focused node — the
   * moment to remove it (and its edges) from consumer state.
   */
  onDelete?: () => void
}

/**
 * Reads whether a pointer-down landed on something that owns its own
 * gesture — a control, editable text, a connection handle, or a canvas
 * nested inside the node — so dragging never steals from it.
 *
 * @param target - The event target.
 * @param node - The node element considering the gesture.
 * @returns Whether the node should leave the gesture alone.
 */
function targetOwnsGesture(target: Element, node: Element): boolean {
  const owner = target.closest(
    'button, a, input, textarea, select, [contenteditable="true"], [data-slot="workflow-canvas-handle"], [data-workflow-canvas-no-drag]',
  )

  // A control marked drag-through — the node's own collapse toggle — works
  // like a window title bar: a clean click activates it, while a movement
  // past the drag threshold moves the node (and the trailing click is
  // suppressed before it can reach the control).
  if (owner !== null && !owner.hasAttribute("data-workflow-canvas-drag-through")) {
    return true
  }

  // A canvas nested inside this node owns its own panning; the canvas this
  // node lives on does not block the drag.
  const nearestCanvas = target.closest('[data-slot="workflow-canvas"]')

  return nearestCanvas !== null && node.contains(nearestCanvas)
}

/**
 * One node on a workflow canvas: an absolutely placed box that renders any
 * content, drags with the pointer, moves with arrow keys while focused, and
 * anchors the edges that reference its `nodeId`.
 *
 * The node is fully controlled when `position` is provided. Compose
 * `WorkflowCanvasNodeHandle` children to offer connection points on its
 * sides; they reveal on hover, on focus, and while a connection is being
 * drawn anywhere on the canvas. Controls, editable fields, nested
 * canvases, and anything marked `data-workflow-canvas-no-drag` own their
 * own gestures and never start a drag; styling the node itself with CSS
 * `resize` keeps its native grip working, presses there resizing the node
 * instead of dragging it.
 *
 * @param props - The node id, controlled or uncontrolled position, change
 * callbacks, selection state, and native container properties.
 * @returns The positioned node element providing node context.
 */
function WorkflowCanvasNode({
  nodeId,
  position: positionProp,
  defaultPosition,
  onPositionChange,
  onPositionCommit,
  selected,
  collapsed: collapsedProp,
  defaultCollapsed = false,
  onCollapsedChange,
  onDelete,
  className,
  style,
  children,
  ref,
  onPointerDown,
  onPointerMove,
  onPointerUp,
  onPointerCancel,
  onKeyDown,
  onClick,
  onClickCapture,
  ...props
}: WorkflowCanvasNodeProps) {
  const canvas = useWorkflowCanvas("WorkflowCanvasNode")
  const elementRef = React.useRef<HTMLDivElement>(null)
  const composedRef = React.useMemo(
    () => composeWorkflowCanvasRefs(elementRef, ref),
    [ref],
  )
  const storedGeometry = useWorkflowCanvasNodeGeometry(nodeId)
  const dragStateRef = React.useRef<WorkflowCanvasNodeDragState | null>(null)
  const suppressClickRef = React.useRef(false)
  // Detaches the document-level settle for a press that claimed the board.
  const detachClaimRef = React.useRef<(() => void) | null>(null)
  // Pending trailing commit for a run of resize-driven clamps.
  const resizeCommitRef = React.useRef<ReturnType<typeof setTimeout> | null>(
    null,
  )
  // Carries an uncontrolled node's live position across a nodeId change,
  // where the old registration is removed and a new one created.
  const carriedPositionRef = React.useRef<WorkflowCanvasPoint | null>(null)
  const [dragging, setDragging] = React.useState(false)
  // The node's own hover and focus-within, tracked here rather than read
  // from a CSS group: a group selector matches ANY ancestor carrying the
  // class, so a host node wrapping a nested canvas would reveal every
  // handle inside that canvas at once.
  const [hovered, setHovered] = React.useState(false)
  const [focusWithin, setFocusWithin] = React.useState(false)
  const [uncontrolledCollapsed, setUncontrolledCollapsed] =
    React.useState(defaultCollapsed)
  const resolvedCollapsed = collapsedProp ?? uncontrolledCollapsed

  const isControlled = positionProp !== undefined

  // In the render where nodeId changes, the new id has no geometry yet;
  // the old id's position (still registered until effects run) carries
  // over so the node never paints a frame at its default position.
  const lastNodeIdRef = React.useRef(nodeId)
  // The id of the most recent render, so a cleanup can tell a rename —
  // where the element survives — from a real unmount.
  const renderedNodeIdRef = React.useRef(nodeId)
  renderedNodeIdRef.current = nodeId
  const renderCarried =
    lastNodeIdRef.current !== nodeId && positionProp === undefined
      ? canvas.geometry.get(lastNodeIdRef.current)
      : undefined

  const resolvedPosition =
    positionProp ??
    (storedGeometry
      ? { x: storedGeometry.x, y: storedGeometry.y }
      : undefined) ??
    (renderCarried
      ? { x: renderCarried.x, y: renderCarried.y }
      : undefined) ??
    defaultPosition ?? { x: 0, y: 0 }

  const resolvedPositionRef = React.useRef(resolvedPosition)
  resolvedPositionRef.current = resolvedPosition

  const callbacksRef = React.useRef({ onPositionChange, onPositionCommit })
  callbacksRef.current = { onPositionChange, onPositionCommit }

  const isControlledRef = React.useRef(isControlled)
  isControlledRef.current = isControlled

  React.useLayoutEffect(() => {
    lastNodeIdRef.current = nodeId

    const element = elementRef.current
    const carried = carriedPositionRef.current
    carriedPositionRef.current = null
    const initial = carried ?? resolvedPositionRef.current

    canvas.geometry.setPosition(nodeId, initial.x, initial.y)

    if (element) {
      canvas.geometry.setSize(nodeId, element.offsetWidth, element.offsetHeight)
    }

    return () => {
      // A node unmounting mid-drag would strand its claim on the board,
      // leaving the canvas refusing every later background press.
      const abandoned = dragStateRef.current

      if (abandoned) {
        dragStateRef.current = null
        detachClaimRef.current?.()
        canvas.releaseNodeDrag(abandoned.pointerId)

        // A rename runs this cleanup while the element stays mounted, so
        // the gesture has to be settled rather than merely dropped: the
        // node would otherwise keep its grabbing cursor and raised layer
        // for good, and the moves already reported through
        // onPositionChange would never be committed.
        if (renderedNodeIdRef.current !== nodeId) {
          setDragging(false)

          if (abandoned.moved) {
            suppressClickRef.current = true
            callbacksRef.current.onPositionCommit?.(abandoned.latestPosition)
          }

          const element = elementRef.current

          if (element?.hasPointerCapture(abandoned.pointerId)) {
            element.releasePointerCapture(abandoned.pointerId)
          }
        }
      }

      // A renamed node keeps its place: the position rides across to the
      // next registration instead of resetting to the default.
      const parting = canvas.geometry.get(nodeId)
      carriedPositionRef.current = parting
        ? { x: parting.x, y: parting.y }
        : null

      canvas.geometry.remove(nodeId)

      // A connection can't finish once its source node is gone; drop it so
      // no line lingers pointing at nothing.
      const pending = canvas.connection.get()

      if (pending && pending.source === nodeId) {
        canvas.connection.set(null)
      }
    }
  }, [canvas.connection, canvas.geometry, nodeId])

  React.useLayoutEffect(() => {
    // A controlled node mirrors its prop into the geometry store so the
    // edges attached to it follow the consumer's state.
    if (positionProp) {
      canvas.geometry.setPosition(nodeId, positionProp.x, positionProp.y)
    }
  }, [canvas.geometry, nodeId, positionProp])

  const applyPosition = React.useCallback(
    (next: WorkflowCanvasPoint, trigger: WorkflowCanvasNodeTrigger) => {
      if (!isControlledRef.current) {
        canvas.geometry.setPosition(nodeId, next.x, next.y)
      }

      callbacksRef.current.onPositionChange?.(next, { trigger })
    },
    [canvas.geometry, nodeId],
  )

  React.useEffect(() => {
    const element = elementRef.current

    if (!element || typeof ResizeObserver === "undefined") {
      return
    }

    const observer = new ResizeObserver(() => {
      canvas.geometry.setSize(nodeId, element.offsetWidth, element.offsetHeight)

      // A node that grew may now overhang the canvas bounds. Re-clamping
      // here keeps it inside; without it the next drag or arrow press
      // would clamp for the first time and jump backwards by the growth.
      const bounds = canvas.getBounds()

      if (bounds) {
        const current = resolvedPositionRef.current
        const clamped = clampPositionToBounds(
          current,
          { width: element.offsetWidth, height: element.offsetHeight },
          bounds,
        )

        if (clamped.x !== current.x || clamped.y !== current.y) {
          applyPosition(clamped, "resize")

          // A ResizeObserver fires every frame a size changes, but a
          // commit is promised once per settled gesture — so the trailing
          // call is rescheduled until the resizing stops.
          if (resizeCommitRef.current !== null) {
            clearTimeout(resizeCommitRef.current)
          }

          resizeCommitRef.current = setTimeout(() => {
            resizeCommitRef.current = null
            callbacksRef.current.onPositionCommit?.(
              resolvedPositionRef.current,
            )
          }, 120)
        }
      }
    })

    observer.observe(element)

    return () => {
      observer.disconnect()

      if (resizeCommitRef.current !== null) {
        clearTimeout(resizeCommitRef.current)
        resizeCommitRef.current = null
      }
    }
  }, [applyPosition, canvas, canvas.boundsKey, canvas.geometry, nodeId])

  const handlePointerDown = (event: React.PointerEvent<HTMLDivElement>) => {
    onPointerDown?.(event)

    // A second finger belongs to a pinch, never to a node drag; it falls
    // through untouched. (Real pointers only: synthetic test events have
    // no pointer type and report isPrimary false.)
    if (!event.isPrimary && (event.pointerType as string) !== "") {
      return
    }

    // A node styled with a native CSS resize keeps its grip: a press on
    // the grip corner resizes the node instead of dragging it — and never
    // pans a read-only canvas underneath the resize either.
    if (event.button === 0) {
      const computedStyle = getComputedStyle(event.currentTarget)

      if (computedStyle.resize !== "none") {
        const rect = event.currentTarget.getBoundingClientRect()
        const gripExtent =
          24 * canvas.getViewport().zoom * canvas.getScreenScale()
        // The native grip sits at the inline-end corner: bottom-right in
        // LTR, bottom-left in RTL.
        const onGripX =
          computedStyle.direction === "rtl"
            ? event.clientX <= rect.left + gripExtent
            : event.clientX >= rect.right - gripExtent

        if (onGripX && event.clientY >= rect.bottom - gripExtent) {
          event.stopPropagation()
          return
        }
      }
    }

    // A read-only canvas has no node dragging; the press falls through to
    // the canvas so it pans from anywhere.
    if (canvas.readOnly) {
      return
    }

    // The node isolates its gestures so dragging never bubbles into an
    // ancestor node or pans the canvas underneath.
    event.stopPropagation()

    if (
      event.defaultPrevented ||
      event.button !== 0 ||
      dragStateRef.current ||
      targetOwnsGesture(event.target as Element, event.currentTarget)
    ) {
      return
    }

    // No pointer capture yet: capturing on press would retarget the
    // trailing click to the node, so a clean click on a drag-through
    // control (the collapse toggle) could never activate it. The capture
    // happens the moment the movement becomes a drag.
    dragStateRef.current = {
      pointerId: event.pointerId,
      startClientX: event.clientX,
      startClientY: event.clientY,
      lastClientX: event.clientX,
      lastClientY: event.clientY,
      freePosition: resolvedPositionRef.current,
      latestPosition: resolvedPositionRef.current,
      moved: false,
    }

    // Claimed from the press, not from the drag threshold: in between, a
    // second finger on the background would otherwise pan the plane out
    // from under the held node and fire a spurious dismissal.
    canvas.claimNodeDrag(event.pointerId)

    // Without capture the release can land anywhere, so the claim is
    // settled from the document — a press that slips off the node and
    // lifts elsewhere must never strand it, which would leave the canvas
    // refusing every later background press.
    const ownerDocument = event.currentTarget.ownerDocument
    const settleClaim = (settleEvent: PointerEvent) => {
      if (settleEvent.pointerId !== event.pointerId) {
        return
      }

      detachClaimRef.current?.()

      if (
        dragStateRef.current?.pointerId === settleEvent.pointerId &&
        !dragStateRef.current.moved
      ) {
        dragStateRef.current = null
      }

      canvas.releaseNodeDrag(settleEvent.pointerId)
    }

    detachClaimRef.current?.()
    ownerDocument.addEventListener("pointerup", settleClaim, true)
    ownerDocument.addEventListener("pointercancel", settleClaim, true)
    detachClaimRef.current = () => {
      detachClaimRef.current = null
      ownerDocument.removeEventListener("pointerup", settleClaim, true)
      ownerDocument.removeEventListener("pointercancel", settleClaim, true)
    }
  }

  const handlePointerMove = (event: React.PointerEvent<HTMLDivElement>) => {
    onPointerMove?.(event)

    const dragState = dragStateRef.current

    if (!dragState || dragState.pointerId !== event.pointerId) {
      return
    }

    // Without capture (deferred until the drag starts), a press that slips
    // off the node before moving 3px never delivers its release here — a
    // mouse keeps its pointer id, so a later button-less hover would match
    // this state and drag with no button held. A move without the primary
    // button is a dead gesture. (Real pointers only: synthetic test events
    // report no buttons at all.)
    if ((event.pointerType as string) !== "" && (event.buttons & 1) === 0) {
      dragStateRef.current = null
      setDragging(false)
      detachClaimRef.current?.()
      canvas.releaseNodeDrag(event.pointerId)

      if (event.currentTarget.hasPointerCapture(event.pointerId)) {
        event.currentTarget.releasePointerCapture(event.pointerId)
      }

      if (dragState.moved) {
        callbacksRef.current.onPositionCommit?.(dragState.latestPosition)
      }

      return
    }

    // A canvas turning read-only mid-gesture settles the drag where it
    // stands: the moves already applied are real, so they are committed
    // rather than left unreported.
    if (canvas.readOnly) {
      dragStateRef.current = null
      setDragging(false)
      detachClaimRef.current?.()
      canvas.releaseNodeDrag(event.pointerId)

      if (event.currentTarget.hasPointerCapture(event.pointerId)) {
        event.currentTarget.releasePointerCapture(event.pointerId)
      }

      if (dragState.moved) {
        suppressClickRef.current = true
        callbacksRef.current.onPositionCommit?.(dragState.latestPosition)
      }

      return
    }

    // A tiny wobble under the pointer stays a click, not a drag.
    if (
      !dragState.moved &&
      Math.hypot(
        event.clientX - dragState.startClientX,
        event.clientY - dragState.startClientY,
      ) < 3
    ) {
      return
    }

    if (!dragState.moved) {
      dragState.moved = true
      setDragging(true)

      try {
        event.currentTarget.setPointerCapture(event.pointerId)
      } catch {
        // Synthetic pointer events (tests) have no capturable pointer id;
        // dragging still works through the element's own move events.
      }
    }

    // Each step converts only the movement since the previous step, at the
    // scale in force right now — so a wheel zoom landing mid-drag rebases
    // the gesture instead of displacing the node. Client pixels shrink to
    // canvas units through the canvas' own zoom and any ancestor scaling.
    const scale = canvas.getViewport().zoom * canvas.getScreenScale()
    const geometry = canvas.geometry.get(nodeId)
    // The pointer's own travel accumulates unclamped; the bounds are
    // applied only to what is rendered, so an overshoot is remembered and
    // the node returns to the cursor instead of leading it back.
    const free = {
      x:
        dragState.freePosition.x +
        (event.clientX - dragState.lastClientX) / scale,
      y:
        dragState.freePosition.y +
        (event.clientY - dragState.lastClientY) / scale,
    }
    const next = clampPositionToBounds(
      free,
      { width: geometry?.width ?? 0, height: geometry?.height ?? 0 },
      canvas.getBounds(),
    )

    dragState.lastClientX = event.clientX
    dragState.lastClientY = event.clientY
    dragState.freePosition = free
    dragState.latestPosition = next
    applyPosition(next, "pointer")
  }

  const handlePointerEnd = (event: React.PointerEvent<HTMLDivElement>) => {
    const dragState = dragStateRef.current

    if (!dragState || dragState.pointerId !== event.pointerId) {
      return
    }

    dragStateRef.current = null
    setDragging(false)
    detachClaimRef.current?.()
    canvas.releaseNodeDrag(event.pointerId)

    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId)
    }

    if (dragState.moved) {
      // Only a released pointer produces a trailing click; a cancelled
      // gesture must not leave the suppression armed for the next click.
      if (event.type !== "pointercancel") {
        suppressClickRef.current = true
      }

      callbacksRef.current.onPositionCommit?.(dragState.latestPosition)
    }
  }

  const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event)

    // Movement keys act on the node itself, never on a focused control
    // inside it; a read-only canvas has no node movement or deletion.
    if (
      event.defaultPrevented ||
      event.target !== event.currentTarget ||
      canvas.readOnly
    ) {
      return
    }

    if ((event.key === "Delete" || event.key === "Backspace") && onDelete) {
      event.preventDefault()
      event.stopPropagation()

      // The consumer decides whether anything is deleted — it may refuse,
      // or confirm first — so focus is only rescued if the node actually
      // left the document, matching how a dismissal recovers focus.
      const activeBefore = event.currentTarget

      onDelete()
      queueMicrotask(() => {
        if (!activeBefore.isConnected) {
          canvas.getRootElement()?.focus()
        }
      })

      return
    }

    const step = canvas.keyboardMoveStep * (event.shiftKey ? 4 : 1)
    const current = resolvedPositionRef.current
    let next: WorkflowCanvasPoint | undefined

    switch (event.key) {
      case "ArrowLeft":
        next = { x: current.x - step, y: current.y }
        break
      case "ArrowRight":
        next = { x: current.x + step, y: current.y }
        break
      case "ArrowUp":
        next = { x: current.x, y: current.y - step }
        break
      case "ArrowDown":
        next = { x: current.x, y: current.y + step }
        break
    }

    if (!next) {
      return
    }

    event.preventDefault()
    event.stopPropagation()

    const geometry = canvas.geometry.get(nodeId)
    const clamped = clampPositionToBounds(
      next,
      { width: geometry?.width ?? 0, height: geometry?.height ?? 0 },
      canvas.getBounds(),
    )

    applyPosition(clamped, "keyboard")
    callbacksRef.current.onPositionCommit?.(clamped)

    // The move may have walked the node off screen; nudge the viewport so
    // keyboard users can see what they are moving.
    canvas.revealRegion({
      x: clamped.x,
      y: clamped.y,
      width: geometry?.width ?? 0,
      height: geometry?.height ?? 0,
    })
  }

  // The click that ends a drag is part of the drag, not an activation —
  // for the node's own onClick AND for any drag-through control (the
  // collapse toggle) the gesture happened to start on, so suppression
  // runs in the capture phase, before the click can reach either.
  const handleClickCapture = (event: React.MouseEvent<HTMLDivElement>) => {
    // Only a pointer-trailing click (detail >= 1) can conclude a drag; a
    // keyboard activation arrives with detail 0 and must never be eaten
    // by suppression a click-less touch drag left armed.
    if (suppressClickRef.current && event.detail !== 0) {
      suppressClickRef.current = false
      event.preventDefault()
      event.stopPropagation()
      return
    }

    onClickCapture?.(event)
  }

  const handleClick = (event: React.MouseEvent<HTMLDivElement>) => {
    onClick?.(event)
  }

  const onCollapsedChangeRef = React.useRef(onCollapsedChange)
  onCollapsedChangeRef.current = onCollapsedChange

  const setCollapsed = React.useCallback(
    (next: boolean) => {
      if (collapsedProp === undefined) {
        setUncontrolledCollapsed(next)
      }

      onCollapsedChangeRef.current?.(next)
    },
    [collapsedProp],
  )

  const nodeContextValue = React.useMemo<WorkflowCanvasNodeContextValue>(
    () => ({
      nodeId,
      collapsed: resolvedCollapsed,
      setCollapsed,
      revealed: hovered || focusWithin,
    }),
    [nodeId, resolvedCollapsed, setCollapsed, hovered, focusWithin],
  )

  return (
    <WorkflowCanvasNodeContext.Provider value={nodeContextValue}>
      {/* Consumer props spread first so the attributes the node owns
          (slot, position transform, gesture handlers) always win. */}
      <div
        role="group"
        tabIndex={0}
        {...props}
        ref={composedRef}
        data-slot="workflow-canvas-node"
        data-node-id={nodeId}
        data-selected={selected ? "true" : undefined}
        data-collapsed={resolvedCollapsed ? "true" : undefined}
        data-dragging={dragging ? "true" : undefined}
        className={cn(
          "group/workflow-node absolute top-0 left-0 box-border select-none data-[dragging=true]:cursor-grabbing data-[dragging=true]:z-10",
          canvas.readOnly ? "cursor-default" : "cursor-grab",
          // Selection reads as a soft halo around the node rather than a
          // hard ring, which would double up with the border most node
          // content already draws.
          "rounded-2xl data-[selected=true]:shadow-[0_0_0_4px_color-mix(in_oklab,var(--ring)_15%,transparent),0_10px_28px_-12px_color-mix(in_oklab,var(--ring)_55%,transparent)]",
          "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
          className,
        )}
        style={{
          ...style,
          // The node's placement composes with — never yields to — a
          // transform the consumer styles on, such as a hover scale.
          transform: `translate(${resolvedPosition.x}px, ${resolvedPosition.y}px)${
            typeof style?.transform === "string" ? ` ${style.transform}` : ""
          }`,
        }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={(event) => {
          onPointerUp?.(event)
          handlePointerEnd(event)
        }}
        onPointerCancel={(event) => {
          onPointerCancel?.(event)
          handlePointerEnd(event)
        }}
        onPointerDownCapture={(event) => {
          props.onPointerDownCapture?.(event)

          if (!event.isPrimary && (event.pointerType as string) !== "") {
            return
          }

          // A touch drag ends without a trailing click, so suppression
          // left armed from a previous gesture retires when any new press
          // begins. The capture phase is the only place that sees them
          // all: a press inside a nested canvas, an inner node, or a
          // handle stops pointerdown before it could bubble to this node.
          suppressClickRef.current = false
        }}
        onKeyDown={handleKeyDown}
        onClickCapture={handleClickCapture}
        onClick={handleClick}
        onPointerEnter={(event) => {
          props.onPointerEnter?.(event)
          setHovered(true)
        }}
        onPointerLeave={(event) => {
          props.onPointerLeave?.(event)
          setHovered(false)
        }}
        onBlur={(event) => {
          props.onBlur?.(event)

          if (
            !event.currentTarget.contains(event.relatedTarget as Node | null)
          ) {
            setFocusWithin(false)
          }
        }}
        onFocus={(event) => {
          props.onFocus?.(event)
          setFocusWithin(true)

          // The canvas clips rather than scrolls, so a node reached by Tab
          // could sit off screen with nothing to reveal it. Panning to it
          // keeps keyboard focus visible. A pointer press focuses the node
          // too, and panning then would tear it out from under the cursor,
          // so only keyboard focus (:focus-visible) reveals — tested on
          // whatever actually received focus, since backward tabbing
          // reaches a node's handles before the node itself.
          const focused = event.target as Element

          if (
            typeof focused.matches === "function" &&
            focused.matches(":focus-visible")
          ) {
            const geometry = canvas.geometry.get(nodeId)

            if (geometry) {
              canvas.revealRegion(geometry)
            }
          }
        }}
      >
        {children}
      </div>
    </WorkflowCanvasNodeContext.Provider>
  )
}

const handleSideClasses: Record<WorkflowCanvasSide, string> = {
  top: "top-0 left-1/2 -translate-x-1/2 -translate-y-1/2",
  right: "top-1/2 right-0 translate-x-1/2 -translate-y-1/2",
  bottom: "bottom-0 left-1/2 -translate-x-1/2 translate-y-1/2",
  left: "top-1/2 left-0 -translate-x-1/2 -translate-y-1/2",
}

/** Properties accepted by one connection handle. */
interface WorkflowCanvasNodeHandleProps extends React.ComponentProps<"button"> {
  /** The node side the handle sits on and connections attach through. */
  side: WorkflowCanvasSide
  /**
   * A custom indicator — an icon, a badge, any element — rendered in place
   * of the default dot. The handle keeps its placement, reveal, and
   * connection behavior around whatever is passed.
   */
  children?: React.ReactNode
}

/**
 * A connection point on one side of a node. Dragging from a handle draws a
 * live connection line; releasing over another node or handle reports the
 * connection through the canvas' `onConnect`. With the keyboard, activating
 * one handle starts the connection and activating a handle on another node
 * completes it; Escape abandons it.
 *
 * Handles stay hidden until the node is hovered or focused, or while any
 * connection is being drawn, so they read as an affordance near the edges
 * without cluttering the graph. Pass children to replace the default dot
 * with a custom indicator.
 *
 * @param props - The side to sit on, an optional custom indicator, and
 * native button properties.
 * @returns The handle button element.
 */
function WorkflowCanvasNodeHandle({
  side,
  className,
  children,
  onPointerDown,
  onPointerMove,
  onPointerUp,
  onPointerCancel,
  onClick,
  ...props
}: WorkflowCanvasNodeHandleProps) {
  const canvas = useWorkflowCanvas("WorkflowCanvasNodeHandle")
  const node = React.useContext(WorkflowCanvasNodeContext)

  if (node === null) {
    throw new Error(
      "WorkflowCanvasNodeHandle must be used within a WorkflowCanvasNode.",
    )
  }

  const { nodeId } = node
  const draggingRef = React.useRef<number | null>(null)
  // Whether the imminent click concludes a pointer gesture on this handle,
  // as opposed to a keyboard or assistive-technology activation.
  const pointerSessionRef = React.useRef(false)

  // The snapshot collapses to a tiny string so pointer moves elsewhere on
  // the canvas never re-render this handle. It carries both flags the
  // handle presents: whether it armed the pending connection, and whether
  // ANY connection is in flight on THIS canvas — read from the handle's
  // own context rather than a CSS group selector, which would match any
  // ancestor canvas and leak an outer canvas' state into a nested one.
  const connectionFlags = React.useSyncExternalStore(
    canvas.connection.subscribe,
    () => {
      const pending = canvas.connection.get()

      return `${
        pending !== null &&
        pending.source === nodeId &&
        pending.sourceSide === side
          ? 1
          : 0
      }${pending !== null ? 1 : 0}`
    },
    () => "00",
  )
  const isConnectionSource = connectionFlags[0] === "1"
  const isConnecting = connectionFlags[1] === "1"

  // A read-only canvas draws no connections, so the handle leaves the DOM
  // rather than hiding: as a class, `hidden` shares tailwind-merge's
  // display group with the `block`/`flex` below and would be stripped.
  if (canvas.readOnly) {
    return null
  }

  const settlePointerConnection = (clientX: number, clientY: number) => {
    const ownRoot = canvas.getRootElement()
    const dropped = document.elementFromPoint(clientX, clientY)

    // Only elements of THIS canvas can receive the connection: a nested
    // subflow renders its own nodes and handles with the same slots, and
    // a drop on one of them must resolve to its host node instead.
    const belongsToOwnCanvas = (element: Element): boolean =>
      element.closest('[data-slot="workflow-canvas"]') === ownRoot

    const handleTarget = dropped?.closest<HTMLElement>(
      '[data-slot="workflow-canvas-handle"]',
    )

    if (
      handleTarget?.dataset.nodeId &&
      handleTarget.dataset.side &&
      belongsToOwnCanvas(handleTarget)
    ) {
      canvas.completeConnection(
        handleTarget.dataset.nodeId,
        handleTarget.dataset.side as WorkflowCanvasSide,
      )
      return
    }

    let nodeTarget =
      dropped?.closest<HTMLElement>('[data-slot="workflow-canvas-node"]') ??
      null

    // Walk out of foreign (nested) canvases until reaching a node this
    // canvas owns, so a drop on a subflow preview connects to its host.
    while (nodeTarget && !belongsToOwnCanvas(nodeTarget)) {
      nodeTarget =
        nodeTarget.parentElement?.closest<HTMLElement>(
          '[data-slot="workflow-canvas-node"]',
        ) ?? null
    }

    if (nodeTarget?.dataset.nodeId) {
      const geometry = canvas.geometry.get(nodeTarget.dataset.nodeId)
      const point = canvas.clientPointToCanvasPoint(clientX, clientY)

      canvas.completeConnection(
        nodeTarget.dataset.nodeId,
        geometry ? nearestNodeSide(geometry, point) : "left",
      )
      return
    }

    // Released over this canvas' open background: report the drop point so
    // the consumer can offer follow-up UI there (for example a palette of
    // nodes to create). A release outside the canvas is a plain cancel.
    if (dropped && ownRoot?.contains(dropped)) {
      canvas.endConnectionAtPoint(
        canvas.clientPointToCanvasPoint(clientX, clientY),
      )
    } else {
      canvas.cancelConnection()
    }
  }

  return (
    <button
      type="button"
      aria-label={`Connect ${side}`}
      aria-pressed={isConnectionSource}
      {...props}
      data-slot="workflow-canvas-handle"
      data-node-id={nodeId}
      data-side={side}
      data-connecting={isConnecting ? "true" : undefined}
      className={cn(
        "absolute box-border cursor-crosshair appearance-none border-0 bg-transparent p-0",
        // Own-context state, never an ancestor group selector: a nested
        // editable canvas keeps its handles even inside a read-only outer
        // one, and an outer connection never reveals inner handles.
        // Hidden handles are inert too: an opacity-0 button would still
        // hit-test, stealing touch drags and taps at the node's edges.
        "pointer-events-none opacity-0",
        // The reveal follows THIS node's own hover and focus, read from
        // node context: an ancestor group selector would match the host
        // node of a nested canvas and light up every handle inside it.
        node.revealed && "pointer-events-auto opacity-100",
        "data-[connecting=true]:pointer-events-auto data-[connecting=true]:opacity-100 focus-visible:pointer-events-auto",
        "transition-[opacity,scale] [transition-duration:var(--nessa-motion-duration-fast)] [transition-timing-function:var(--nessa-motion-easing-standard)] motion-reduce:transition-none",
        "focus-visible:opacity-100 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
        // The dot stays small and quiet, but the grab and drop area does
        // not: a ::before pad extends the hit box well past the visual, so
        // a connection can be started — and released — without pixel
        // precision on a 10px target that sits half outside the card.
        "before:absolute before:-inset-2 before:content-['']",
        children == null
          ? "block size-2.5 rounded-full border-[1.5px] border-ring/40 bg-card hover:scale-125 hover:border-ring hover:bg-ring/15 aria-pressed:scale-125 aria-pressed:border-ring aria-pressed:bg-ring/20 data-[connecting=true]:border-ring data-[connecting=true]:bg-ring/15"
          : "flex items-center justify-center",
        handleSideClasses[side],
        className,
      )}
      onPointerDown={(event) => {
        onPointerDown?.(event)

        // A second finger belongs to a pinch, never to a connection.
        if (!event.isPrimary && (event.pointerType as string) !== "") {
          return
        }

        // Only a main-button press can end in a trailing click; anything
        // else (right-click, cancelled touch) must not arm the flag it
        // could never clear.
        if (event.button === 0) {
          pointerSessionRef.current = true
        }

        // A read-only canvas draws no connections; the press falls through
        // to the canvas so it pans instead.
        if (canvas.readOnly) {
          return
        }

        event.stopPropagation()

        if (
          event.defaultPrevented ||
          event.button !== 0 ||
          draggingRef.current !== null
        ) {
          return
        }

        // A press while a keyboard-armed connection waits settles it:
        // completing on another node, cancelling back on its source. A
        // connection a pointer is actively dragging belongs to that
        // pointer alone — other presses stay inert until it settles.
        const pending = canvas.connection.get()

        if (pending !== null) {
          if (pending.mode === "keyboard") {
            if (pending.source === nodeId) {
              canvas.cancelConnection()
            } else {
              canvas.completeConnection(nodeId, side)
            }
          }

          return
        }

        try {
          event.currentTarget.setPointerCapture(event.pointerId)
        } catch {
          // Synthetic pointer events (tests) have no capturable pointer id;
          // connecting still works through the element's own move events.
        }

        draggingRef.current = event.pointerId
        canvas.beginConnection(nodeId, side, "pointer")
      }}
      onPointerMove={(event) => {
        onPointerMove?.(event)

        if (draggingRef.current !== event.pointerId) {
          return
        }

        // A canvas turning read-only mid-gesture drops the connection.
        if (canvas.readOnly) {
          draggingRef.current = null
          return
        }

        canvas.moveConnection(event.clientX, event.clientY)
      }}
      onPointerUp={(event) => {
        onPointerUp?.(event)

        if (draggingRef.current !== event.pointerId) {
          return
        }

        draggingRef.current = null
        event.stopPropagation()

        if (event.currentTarget.hasPointerCapture(event.pointerId)) {
          event.currentTarget.releasePointerCapture(event.pointerId)
        }

        if (!canvas.readOnly) {
          settlePointerConnection(event.clientX, event.clientY)
        }
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event)

        // A cancelled gesture produces no trailing click to clear the
        // session flag, so it retires here.
        pointerSessionRef.current = false

        if (draggingRef.current === event.pointerId) {
          draggingRef.current = null
          canvas.cancelConnection()
        }
      }}
      onClick={(event) => {
        onClick?.(event)

        if (event.defaultPrevented) {
          return
        }

        // Drawing a connection is not activating the node, so the click
        // never reaches the node's own handling — pointer or keyboard.
        event.stopPropagation()

        // A click concluding this handle's own pointer gesture was
        // already handled by that gesture. Anything else — keyboard
        // activations (detail 0, immune to a stale flag left by a
        // click-less touch), or the bare clicks assistive technology
        // sends — is an activation.
        const followsPointerGesture =
          pointerSessionRef.current && event.detail !== 0

        pointerSessionRef.current = false

        if (followsPointerGesture || canvas.readOnly) {
          return
        }

        const pending = canvas.connection.get()

        if (pending === null) {
          canvas.beginConnection(nodeId, side, "keyboard")
        } else if (pending.mode !== "keyboard") {
          // A connection a pointer is actively dragging belongs to that
          // pointer alone; an activation elsewhere stays inert.
          return
        } else if (pending.source === nodeId) {
          canvas.cancelConnection()
        } else {
          canvas.completeConnection(nodeId, side)
        }
      }}
    >
      {children}
    </button>
  )
}

/** Properties accepted by the node collapse toggle. */
interface WorkflowCanvasNodeToggleProps
  extends React.ComponentProps<"button"> {}

/**
 * A button that folds its node between collapsed and expanded. Place it in
 * the part of the node that stays visible — typically a header row — and
 * the node's `WorkflowCanvasNodeBody` children hide while collapsed, so a
 * whole subflow can shrink to a single pill until it is wanted. Renders a
 * turning chevron by default; pass children for a custom indicator.
 *
 * @param props - Native button properties and an optional custom indicator.
 * @returns The toggle button element.
 */
function WorkflowCanvasNodeToggle({
  className,
  children,
  onClick,
  ...props
}: WorkflowCanvasNodeToggleProps) {
  const node = React.useContext(WorkflowCanvasNodeContext)

  if (node === null) {
    throw new Error(
      "WorkflowCanvasNodeToggle must be used within a WorkflowCanvasNode.",
    )
  }

  return (
    <button
      type="button"
      aria-label="Toggle content"
      aria-expanded={!node.collapsed}
      {...props}
      data-slot="workflow-canvas-node-toggle"
      data-workflow-canvas-drag-through=""
      className={cn(
        "box-border inline-flex size-6 shrink-0 cursor-pointer appearance-none items-center justify-center rounded-md border-0 bg-transparent p-0 text-muted-foreground hover:text-foreground",
        "transition-colors [transition-duration:var(--nessa-motion-duration-fast)] [transition-timing-function:var(--nessa-motion-easing-standard)] motion-reduce:transition-none",
        "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
        className,
      )}
      onClick={(event) => {
        onClick?.(event)

        if (event.defaultPrevented) {
          return
        }

        // Folding a node is not activating it; the node's own click
        // handling stays out of it.
        event.stopPropagation()
        node.setCollapsed(!node.collapsed)
      }}
    >
      {children ?? (
        <svg
          aria-hidden="true"
          viewBox="0 0 10 6"
          className="w-2.5 transition-transform [transition-duration:var(--nessa-motion-duration-fast)] [transition-timing-function:var(--nessa-motion-easing-standard)] motion-reduce:transition-none group-data-[collapsed=true]/workflow-node:-rotate-90"
        >
          <path
            d="M1 1l4 4 4-4"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      )}
    </button>
  )
}

/** Properties accepted by the collapsible node body. */
interface WorkflowCanvasNodeBodyProps extends React.ComponentProps<"div"> {}

/**
 * The part of a node that hides while the node is collapsed. Everything
 * outside the body — the header, its `WorkflowCanvasNodeToggle`, the
 * connection handles — stays visible, and edges re-anchor automatically as
 * the node shrinks and grows.
 *
 * @param props - Native container properties.
 * @returns The collapsible content element.
 */
function WorkflowCanvasNodeBody({
  className,
  ...props
}: WorkflowCanvasNodeBodyProps) {
  return (
    <div
      {...props}
      data-slot="workflow-canvas-node-body"
      className={cn(
        "group-data-[collapsed=true]/workflow-node:hidden",
        className,
      )}
    />
  )
}

export {
  WorkflowCanvasNode,
  WorkflowCanvasNodeBody,
  WorkflowCanvasNodeHandle,
  WorkflowCanvasNodeToggle,
  type WorkflowCanvasNodeBodyProps,
  type WorkflowCanvasNodeHandleProps,
  type WorkflowCanvasNodeProps,
  type WorkflowCanvasNodeToggleProps,
  type WorkflowCanvasNodeTrigger,
}

"use client"

/** @responsibility Renders the edge layer of a workflow canvas: declarative edges that follow their endpoint nodes with auto-aligned sides, optional interactivity and selection, and the live line drawn while a connection gesture is in flight. */

import * as React from "react"

import { cn } from "@/lib/utils"

import {
  useWorkflowCanvas,
  useWorkflowCanvasNodeGeometry,
  useWorkflowCanvasPendingConnection,
} from "./workflow-canvas-context"
import {
  edgeMidpoint,
  edgePath,
  nearestNodeSide,
  nodeAnchorPoint,
  preferredEdgeSides,
  type WorkflowCanvasPoint,
  type WorkflowCanvasSide,
} from "./workflow-canvas-math"

/** The resolved drawing geometry of one edge. */
interface WorkflowCanvasEdgeGeometry {
  /** The SVG path definition of the edge's curve. */
  path: string
  /** Where the edge leaves the source node, in canvas units. */
  sourceAnchor: WorkflowCanvasPoint
  /** Where the edge enters the target node, in canvas units. */
  targetAnchor: WorkflowCanvasPoint
  /** The point halfway along the curve, where labels sit naturally. */
  midpoint: WorkflowCanvasPoint
  /** The side the edge actually leaves from after auto-alignment. */
  sourceSide: WorkflowCanvasSide
  /** The side the edge actually arrives at after auto-alignment. */
  targetSide: WorkflowCanvasSide
}

/** Endpoint options resolved into edge geometry. */
interface WorkflowCanvasEdgeOptions {
  /** The id of the node the edge starts from. */
  source: string
  /** The id of the node the edge ends at. */
  target: string
  /** A fixed source side; omit to let auto-alignment pick one. */
  sourceSide?: WorkflowCanvasSide
  /** A fixed target side; omit to let auto-alignment pick one. */
  targetSide?: WorkflowCanvasSide
  /**
   * Whether unset sides follow the nodes' relative positions, so an edge
   * always takes the most direct route and re-routes as nodes move. Turn
   * off to pin unset sides to the static right-to-left default.
   * @defaultValue true
   */
  autoAlign?: boolean
}

/**
 * Resolves one edge's live drawing geometry, subscribing to just its two
 * endpoint nodes. Build fully custom edge presentations on top of this —
 * anything that can render SVG or a positioned element can be an edge.
 *
 * @param options - The endpoint node ids, optional fixed sides, and the
 * auto-alignment switch.
 * @returns The edge geometry, or undefined until both endpoints are
 * mounted.
 */
function useWorkflowCanvasEdgeGeometry(
  options: WorkflowCanvasEdgeOptions,
): WorkflowCanvasEdgeGeometry | undefined {
  const { source, target, sourceSide, targetSide, autoAlign = true } = options
  const sourceGeometry = useWorkflowCanvasNodeGeometry(source)
  const targetGeometry = useWorkflowCanvasNodeGeometry(target)

  if (!sourceGeometry || !targetGeometry) {
    return undefined
  }

  const preferred = autoAlign
    ? preferredEdgeSides(sourceGeometry, targetGeometry)
    : undefined
  const resolvedSourceSide = sourceSide ?? preferred?.sourceSide ?? "right"
  const resolvedTargetSide = targetSide ?? preferred?.targetSide ?? "left"
  const sourceAnchor = nodeAnchorPoint(sourceGeometry, resolvedSourceSide)
  const targetAnchor = nodeAnchorPoint(targetGeometry, resolvedTargetSide)

  return {
    path: edgePath(
      sourceAnchor,
      resolvedSourceSide,
      targetAnchor,
      resolvedTargetSide,
    ),
    sourceAnchor,
    targetAnchor,
    midpoint: edgeMidpoint(
      sourceAnchor,
      resolvedSourceSide,
      targetAnchor,
      resolvedTargetSide,
    ),
    sourceSide: resolvedSourceSide,
    targetSide: resolvedTargetSide,
  }
}

/** Properties accepted by the canvas edge layer. */
interface WorkflowCanvasEdgesProps extends React.ComponentProps<"svg"> {
  /**
   * The element drawn while a connection gesture is in flight. Pass a
   * styled `WorkflowCanvasConnectionLine` (or any component reading
   * `useWorkflowCanvasPendingConnection`) to restyle it.
   * @defaultValue `<WorkflowCanvasConnectionLine />`
   */
  connectionLine?: React.ReactNode
}

/**
 * The layer edges draw on. Place it inside a `WorkflowCanvasSurface`
 * alongside the nodes — typically before them, so edges run underneath —
 * and compose `WorkflowCanvasEdge` children inside it. The layer also draws
 * the live connection line while one is being dragged from a handle.
 *
 * @param props - Native SVG properties, an optional custom connection line,
 * and the canvas' edges as children.
 * @returns The edge layer element.
 */
function WorkflowCanvasEdges({
  connectionLine,
  className,
  children,
  ...props
}: WorkflowCanvasEdgesProps) {
  return (
    <svg
      width="1"
      height="1"
      {...props}
      data-slot="workflow-canvas-edges"
      className={cn(
        "pointer-events-none absolute top-0 left-0 overflow-visible",
        className,
      )}
    >
      {children}
      {connectionLine ?? <WorkflowCanvasConnectionLine />}
    </svg>
  )
}

/** Properties accepted by one canvas edge. */
interface WorkflowCanvasEdgeProps
  extends Omit<React.ComponentProps<"g">, "children" | "target">,
    WorkflowCanvasEdgeOptions {
  /** Whether the edge presents as selected. */
  selected?: boolean
  /**
   * Whether the edge takes pointer and keyboard interaction: a wide invisible
   * hit area along the curve, a button role, and focusability. Defaults to
   * on exactly when `onClick` or `onDelete` is provided.
   */
  interactive?: boolean
  /**
   * Called when Delete or Backspace is pressed on the focused edge — the
   * moment to remove it from consumer state.
   */
  onDelete?: () => void
  /** Custom SVG content drawn on top of the line — markers, labels, badges. */
  children?: React.ReactNode
  /** Class for the visible line itself; the other properties land on the group. */
  className?: string
}

/**
 * One edge between two nodes. The edge subscribes to just its two endpoint
 * nodes, so it re-renders while either of them moves or resizes and stays
 * inert the rest of the time — even on canvases with thousands of nodes.
 *
 * Sides auto-align by default: the edge leaves and enters whichever facing
 * sides connect the nodes most directly, re-routing live as nodes move.
 * Pass `sourceSide`/`targetSide` to pin a side, or `autoAlign={false}` for
 * the static right-to-left default. With `onClick` (or `interactive`) the
 * edge becomes a focusable button with a generous hit area along the curve;
 * pair it with `selected` to present selection. Style the line through
 * `className`; render custom SVG decorations as children, or build a fully
 * custom edge with `useWorkflowCanvasEdgeGeometry`.
 *
 * The edge renders nothing until both endpoints are mounted, so edges and
 * nodes can be declared in any order.
 *
 * @param props - The endpoint node ids, side and alignment options,
 * selection and interactivity state, and native group properties.
 * @returns The edge group element, or nothing while an endpoint is missing.
 */
function WorkflowCanvasEdge({
  source,
  target,
  sourceSide,
  targetSide,
  autoAlign,
  selected,
  interactive,
  onDelete,
  className,
  children,
  onClick,
  onKeyDown,
  ...props
}: WorkflowCanvasEdgeProps) {
  const { readOnly, getRootElement } = useWorkflowCanvas("WorkflowCanvasEdge")
  const geometry = useWorkflowCanvasEdgeGeometry({
    source,
    target,
    sourceSide,
    targetSide,
    autoAlign,
  })

  if (!geometry) {
    return null
  }

  // A read-only canvas keeps its edges inert end to end: no button role,
  // no focusability, no hit area — so pointer and keyboard agree.
  const isInteractive =
    !readOnly &&
    (interactive ?? (onClick !== undefined || onDelete !== undefined))

  return (
    <g
      role={isInteractive ? "button" : undefined}
      tabIndex={isInteractive ? 0 : undefined}
      // Selection is visible state, so assistive technology hears it too.
      aria-pressed={
        isInteractive && selected !== undefined ? selected : undefined
      }
      {...props}
      data-slot="workflow-canvas-edge"
      data-source={source}
      data-target={target}
      data-selected={selected ? "true" : undefined}
      className={cn(
        // An outline on an SVG group draws a rectangle around the curve's
        // whole bounding box, so focus is presented on the line itself
        // below instead.
        "group/workflow-edge outline-none",
        isInteractive && "cursor-pointer",
      )}
      onClick={onClick}
      onKeyDown={(event) => {
        onKeyDown?.(event)

        // Keys pressed inside a focusable child (a label editor, a badge
        // button) belong to that child, never to the edge.
        if (
          event.defaultPrevented ||
          !isInteractive ||
          event.target !== event.currentTarget
        ) {
          return
        }

        // A focusable edge activates like a button: Enter and Space click it.
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault()
          event.currentTarget.dispatchEvent(
            new MouseEvent("click", { bubbles: true }),
          )
          return
        }

        // A read-only canvas keeps its structure; deletion stays inert.
        if (
          (event.key === "Delete" || event.key === "Backspace") &&
          onDelete &&
          !readOnly
        ) {
          event.preventDefault()
          event.stopPropagation()

          // The consumer decides whether anything is deleted — it may
          // refuse, or confirm first — so focus is only rescued if the
          // edge actually left the document.
          const activeBefore = event.currentTarget

          onDelete()
          queueMicrotask(() => {
            if (!activeBefore.isConnected) {
              getRootElement()?.focus()
            }
          })
        }
      }}
    >
      {isInteractive ? (
        <path
          data-slot="workflow-canvas-edge-hit"
          d={geometry.path}
          fill="none"
          // The grab band widens inversely to zoom so it stays ~16 screen
          // pixels: scaled with the surface it would shrink to a few
          // pixels on a zoomed-out canvas, exactly where edges are hardest
          // to hit. `vector-effect` cannot do this — the zoom is a CSS
          // transform on an HTML ancestor, outside the SVG's own
          // coordinate chain — so the surface publishes its zoom and the
          // band divides by it. The fallback keeps a sane band for an edge
          // layer mounted outside a surface.
          style={{
            strokeWidth: "calc(16 / var(--nessa-workflow-canvas-zoom, 1))",
          }}
          className="stroke-transparent [pointer-events:stroke]"
        />
      ) : null}
      <path
        data-slot="workflow-canvas-edge-line"
        d={geometry.path}
        fill="none"
        strokeLinecap="round"
        className={cn(
          "stroke-border stroke-[2.5]",
          "transition-colors [transition-duration:var(--nessa-motion-duration-fast)] [transition-timing-function:var(--nessa-motion-easing-standard)] motion-reduce:transition-none",
          "group-hover/workflow-edge:stroke-ring group-data-[selected=true]/workflow-edge:stroke-ring",
          "group-focus-visible/workflow-edge:stroke-[3.5] group-focus-visible/workflow-edge:stroke-ring",
          className,
        )}
      />
      {children}
    </g>
  )
}

/** Properties accepted by the live connection line. */
interface WorkflowCanvasConnectionLineProps
  extends React.ComponentProps<"path"> {}

/**
 * The live line drawn while a connection gesture is in flight, from the
 * source handle's anchor to wherever the pointer or keyboard has taken the
 * free end. Rendered automatically by `WorkflowCanvasEdges`; pass a styled
 * one through its `connectionLine` property to restyle it.
 *
 * @param props - Native path properties.
 * @returns The dashed connection path, or nothing while no connection is
 * being drawn.
 */
function WorkflowCanvasConnectionLine({
  className,
  ...props
}: WorkflowCanvasConnectionLineProps) {
  const pending = useWorkflowCanvasPendingConnection()
  // Subscribed, not just read: the source node can move or resize while a
  // connection is being drawn, and the line's anchor must follow it.
  const sourceGeometry = useWorkflowCanvasNodeGeometry(pending?.source ?? "")

  // A keyboard-armed connection has no free end travelling anywhere — the
  // pressed handle and the canvas' connecting state carry the feedback, and
  // no line is drawn that could linger while nodes move.
  if (!pending || pending.mode !== "pointer") {
    return null
  }

  if (!sourceGeometry) {
    return null
  }

  const sourceAnchor = nodeAnchorPoint(sourceGeometry, pending.sourceSide)
  // The free end curves back toward wherever the gesture came from, so
  // approaching a node from any direction reads as a clean arc instead of
  // an S-shaped wave.
  const freeSide = nearestNodeSide(
    { x: pending.point.x, y: pending.point.y, width: 0, height: 0 },
    sourceAnchor,
  )

  return (
    <path
      {...props}
      data-slot="workflow-canvas-connection-line"
      fill="none"
      d={edgePath(sourceAnchor, pending.sourceSide, pending.point, freeSide)}
      className={cn(
        "stroke-ring stroke-[2.5] [stroke-dasharray:6_4]",
        className,
      )}
    />
  )
}

